#!/usr/bin/env python3
import json
import re
import sqlite3
import struct
import sys


def read_varint(buf, pos):
    """Read a SQLite variable-length integer."""
    value = 0
    for _ in range(8):
        if pos >= len(buf):
            raise ValueError("truncated varint")
        byte = buf[pos]
        pos += 1
        value = (value << 7) | (byte & 0x7F)
        if not (byte & 0x80):
            return value, pos
    if pos >= len(buf):
        raise ValueError("truncated varint")
    byte = buf[pos]
    pos += 1
    value = (value << 8) | byte
    return value, pos


def decode_serial_value(serial_type, buf, pos):
    if serial_type == 0:
        return None, pos
    if serial_type == 1:
        n = 1
    elif serial_type == 2:
        n = 2
    elif serial_type == 3:
        n = 3
    elif serial_type == 4:
        n = 4
    elif serial_type == 5:
        n = 6
    elif serial_type == 6:
        n = 8
    elif serial_type == 7:
        raw = buf[pos:pos + 8]
        if len(raw) != 8:
            raise ValueError("truncated float")
        return struct.unpack(">d", raw)[0], pos + 8
    elif serial_type == 8:
        return 0, pos
    elif serial_type == 9:
        return 1, pos
    elif serial_type >= 12 and serial_type % 2 == 0:
        n = (serial_type - 12) // 2
        if pos + n > len(buf):
            raise ValueError("truncated blob")
        return buf[pos:pos + n], pos + n
    elif serial_type >= 13 and serial_type % 2 == 1:
        n = (serial_type - 13) // 2
        if pos + n > len(buf):
            raise ValueError("truncated text")
        return buf[pos:pos + n].decode("utf-8"), pos + n
    else:
        raise ValueError("unsupported serial type")

    raw = buf[pos:pos + n]
    if len(raw) != n:
        raise ValueError("truncated integer")
    return int.from_bytes(raw, "big", signed=True), pos + n


def parse_freeblock_record(rem, ncols):
    """Try to parse a record fragment from a b-tree leaf freeblock.

    The four-byte freeblock header may have overwritten the start of the old
    cell payload.  We attempt the two forms observed in SQLite b-tree pages:
      1. The fragment already starts at the first column's serial type.
      2. The first serial type was overwritten; since it represented the
         INTEGER PRIMARY KEY alias rowid as NULL, reconstruct it as serial 0.
    """
    variants = []
    for leading_serials in ([], [0]):
        try:
            serials = list(leading_serials)
            pos = 0
            remaining = ncols - len(serials)
            for _ in range(remaining):
                serial_type, pos = read_varint(rem, pos)
                serials.append(serial_type)

            values = []
            body_pos = pos
            for serial_type in serials:
                value, body_pos = decode_serial_value(serial_type, rem, body_pos)
                values.append(value)

            if body_pos == len(rem):
                variants.append((serials, values))
        except Exception:
            pass
    return variants


def valid_employee_record(values, columns):
    if len(values) != len(columns):
        return False

    # id is INTEGER PRIMARY KEY, an alias for rowid.  Its record value is
    # normally NULL and the actual id is stored as the cell rowid.
    if values[0] is not None:
        return False

    for idx, ((name, decl_type), value) in enumerate(zip(columns, values)):
        if idx == 0:
            continue
        decl_upper = decl_type.upper()
        if "INT" in decl_upper:
            if not isinstance(value, int) or isinstance(value, bool):
                return False
        elif any(token in decl_upper for token in ("TEXT", "CHAR", "CLOB")):
            if not isinstance(value, str):
                return False
            if not value:
                return False
            if any(ord(ch) < 32 and ch not in "\t\n\r" for ch in value):
                return False
        elif value is None:
            return False

    # Additional sanity checks when the expected employee columns are present.
    names = [name for name, _ in columns]
    if "hire_date" in names:
        hire_date = values[names.index("hire_date")]
        if not isinstance(hire_date, str) or not re.fullmatch(r"\d{4}-\d{2}-\d{2}", hire_date):
            return False
    return True


def page_header_offset(page_no):
    return 100 if page_no == 1 else 0


def collect_leaf_pages(data, page_size, root_page):
    leaves = []
    stack = [root_page]
    seen = set()

    while stack:
        page_no = stack.pop()
        if page_no in seen:
            continue
        seen.add(page_no)

        start = (page_no - 1) * page_size
        page = data[start:start + page_size]
        if len(page) != page_size:
            continue

        hdr = page_header_offset(page_no)
        page_type = page[hdr]
        ncell = struct.unpack(">H", page[hdr + 3:hdr + 5])[0]

        if page_type in (0x02, 0x05):
            # Interior b-tree page.
            children = []
            if page_type == 0x05:
                right = struct.unpack(">I", page[hdr + 8:hdr + 12])[0]
                for i in range(ncell):
                    cell_off = struct.unpack(">H", page[hdr + 12 + 2 * i:hdr + 14 + 2 * i])[0]
                    child = struct.unpack(">I", page[cell_off:cell_off + 4])[0]
                    children.append(child)
                children.append(right)
            else:
                right = struct.unpack(">I", page[hdr + 8:hdr + 12])[0]
                for i in range(ncell):
                    cell_off = struct.unpack(">H", page[hdr + 12 + 2 * i:hdr + 14 + 2 * i])[0]
                    child = struct.unpack(">I", page[cell_off:cell_off + 4])[0]
                    children.append(child)
                children.append(right)
            stack.extend(children)
        elif page_type in (0x0A, 0x0D):
            leaves.append(page_no)

    return leaves


def freeblocks_in_leaf(page, page_size):
    hdr = 0
    off = struct.unpack(">H", page[hdr + 1:hdr + 3])[0]
    seen = set()
    while off:
        if off in seen:
            break
        seen.add(off)
        if off + 4 > page_size:
            break
        nxt, size = struct.unpack(">HH", page[off:off + 4])
        if size < 4 or off + size > page_size:
            break
        yield page[off + 4:off + size]
        off = nxt


def extract_deleted_rowids_from_text(value):
    if not isinstance(value, str):
        return None
    match = re.search(r"(\d+)@", value)
    if not match:
        return None
    return int(match.group(1))


def main():
    if len(sys.argv) != 2:
        print("usage: python3 recover.py DATABASE", file=sys.stderr)
        return 2

    db_path = sys.argv[1]

    con = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
    try:
        cur = con.cursor()
        table_row = cur.execute(
            "SELECT rootpage, sql FROM sqlite_master WHERE type='table' AND name='employees'"
        ).fetchone()
        if table_row is None:
            raise SystemExit("employees table not found")
        root_page = table_row[0]
        columns = [(row[1], row[2]) for row in cur.execute("PRAGMA table_info(employees)")]
        visible = {row[0] for row in cur.execute("SELECT rowid FROM employees")}
    finally:
        con.close()

    data = open(db_path, "rb").read()
    page_size = struct.unpack(">H", data[16:18])[0]
    if page_size == 1:
        page_size = 65536

    ncols = len(columns)
    column_names = [name for name, _ in columns]

    recovered = {}
    for leaf_page in collect_leaf_pages(data, page_size, root_page):
        start = (leaf_page - 1) * page_size
        page = data[start:start + page_size]

        for rem in freeblocks_in_leaf(page, page_size):
            for _serials, values in parse_freeblock_record(rem, ncols):
                if not valid_employee_record(values, columns):
                    continue

                # Find a plausible email-like text value and use its numeric
                # suffix as the deleted rowid.  In this database the email
                # format includes the rowid directly before the @ sign.
                rowid = None
                for value in values:
                    candidate = extract_deleted_rowids_from_text(value)
                    if candidate is not None:
                        rowid = candidate
                        break

                if rowid is None or rowid in visible:
                    continue

                record = {"rowid": rowid}
                for name, value in zip(column_names, values):
                    if name == "id":
                        record[name] = rowid
                    else:
                        record[name] = value

                # If the same deleted cell was encountered twice, keep the
                # first fully valid reconstruction.
                recovered.setdefault(rowid, record)

    records = [recovered[rowid] for rowid in sorted(recovered)]
    print(json.dumps(records, indent=2))


if __name__ == "__main__":
    main()
